import itertools,time,json,collections,shutil,pickle
MASK=(1<<128)-1;start=time.time()
def span(B):
 S=[0]
 for b in B:S += [x^b for x in S]
 return S
def flat(B):return sum(1<<x for x in span(B))
def trans(f,i):
 st=1<<i;lo=LOW[i];d=(f^(f>>st))&lo;return f^d^(d<<st)
